import{_ as s,o as t,c as i,ag as a}from"./chunks/framework.BKVF-9lJ.js";const k=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":1791840224000}'),o={name:"contributing.md"};function n(d,e,c,r,h,l){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>This page summarises how to work on the MFE Forge repository. The canonical sources are <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> and the repository contract in <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/AGENTS.md" target="_blank" rel="noreferrer"><code>AGENTS.md</code></a>. By participating you agree to the <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">code of conduct</a>. Report security issues privately as described in <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>; questions go to <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/SUPPORT.md" target="_blank" rel="noreferrer">SUPPORT.md</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Node.js 20 or newer (CI uses Node 24).</li><li>Bun at the version pinned in the root <code>package.json</code> (<code>&quot;packageManager&quot;: &quot;bun@1.4.2&quot;</code>). CI reads that field through <code>oven-sh/setup-bun</code> with <code>bun-version-file: package.json</code>.</li></ul><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/rez-rayan-zin-eddine/mfe-forge.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mfe-forge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><h2 id="repository-scripts" tabindex="-1">Repository scripts <a class="header-anchor" href="#repository-scripts" aria-label="Permalink to &quot;Repository scripts&quot;">​</a></h2><p>Defined in the root <code>package.json</code>; most delegate to Turborepo.</p><table tabindex="0"><thead><tr><th>Script</th><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>build</code></td><td><code>turbo run build</code></td><td>Build every package with <code>tsup</code></td></tr><tr><td><code>dev</code></td><td><code>turbo run dev</code></td><td>Watch builds</td></tr><tr><td><code>test</code></td><td><code>turbo run test</code></td><td>Vitest in every package</td></tr><tr><td><code>type-check</code></td><td><code>turbo run type-check</code></td><td><code>tsc --noEmit</code> per package</td></tr><tr><td><code>check:package</code></td><td><code>turbo run check:package</code></td><td><code>publint --strict</code> per package</td></tr><tr><td><code>lint</code></td><td><code>eslint .</code></td><td>Lint the repository</td></tr><tr><td><code>format</code></td><td><code>prettier --write .</code></td><td>Format the repository</td></tr><tr><td><code>docs:dev</code> / <code>docs:build</code> / <code>docs:preview</code></td><td><code>vitepress ...</code></td><td>Documentation site in <code>docs/</code></td></tr><tr><td><code>changeset</code></td><td><code>changeset</code></td><td>Add a changeset</td></tr><tr><td><code>version-packages</code></td><td><code>changeset version</code></td><td>Apply pending changesets</td></tr><tr><td><code>release</code></td><td><code>changeset publish</code></td><td>Publish unpublished versions</td></tr></tbody></table><p>Run a focused check first, for example one package&#39;s tests:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/cli</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bunx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/commands/sync.test.ts</span></span></code></pre></div><p>then the full matrix before opening a pull request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type-check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ol><li>Read <code>AGENTS.md</code> and the relevant procedure in <code>.agents/skills/</code>.</li><li>Create a focused branch.</li><li>Inspect existing APIs and tests before editing.</li><li>Add tests for changed behaviour.</li><li>Keep documentation and CLI help truthful. If a doc page claims a command does something, the source must do it.</li><li>Add a changeset (<code>bun changeset</code>) when a published package or a template changes.</li><li>Run the checks above and review <code>git diff --check</code>.</li></ol><p>Architecture decisions go into <code>docs/ai/decisions/</code> as ADRs.</p><h2 id="commits-and-pull-requests" tabindex="-1">Commits and pull requests <a class="header-anchor" href="#commits-and-pull-requests" aria-label="Permalink to &quot;Commits and pull requests&quot;">​</a></h2><p>Use Conventional Commits: <code>feat:</code>, <code>fix:</code>, <code>docs:</code>, <code>test:</code>, <code>refactor:</code>, <code>chore:</code>, optionally with a scope such as <code>feat(core):</code>. A pull request should state the behaviour change, the verification commands you ran and any remaining limitations; the pull request template lists the checklist.</p><h2 id="changesets" tabindex="-1">Changesets <a class="header-anchor" href="#changesets" aria-label="Permalink to &quot;Changesets&quot;">​</a></h2><p>All six packages are in one <strong>fixed</strong> group in <code>.changeset/config.json</code> (<code>mfe-forge</code>, <code>@mfe-forge/core</code>, <code>router</code>, <code>store</code>, <code>design</code>, <code>testing</code>), so any release bumps all of them to the same version. Packages publish with <code>access: public</code>. Changelogs use <code>@changesets/changelog-github</code>, which links each entry to its pull request and author; running <code>changeset version</code> locally therefore needs a <code>GITHUB_TOKEN</code>, for example <code>GITHUB_TOKEN=$(gh auth token) bun run version-packages</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # choose packages and bump type, write a summary</span></span></code></pre></div><p>The project is on <code>0.x</code>: a minor bump may break APIs, a patch is fixes only.</p><h2 id="continuous-integration" tabindex="-1">Continuous integration <a class="header-anchor" href="#continuous-integration" aria-label="Permalink to &quot;Continuous integration&quot;">​</a></h2><p><code>.github/workflows/ci.yml</code> runs on pushes and pull requests to <code>main</code>:</p><table tabindex="0"><thead><tr><th>Job</th><th>Steps</th></tr></thead><tbody><tr><td><code>verify</code></td><td><code>bun install --frozen-lockfile</code>, <code>lint</code>, <code>type-check</code>, <code>build</code>, <code>test</code>, <code>check:package</code></td></tr><tr><td><code>docs</code></td><td><code>bun run docs:build</code> (VitePress with dead-link checking enabled)</td></tr><tr><td><code>changeset-check</code></td><td>Pull requests only. If the diff touches <code>packages/*/src/**</code> or <code>packages/*/package.json</code>, runs <code>changeset status --since=origin/main</code> and fails without a changeset</td></tr></tbody></table><p><code>audit.yml</code> runs <code>bun audit --audit-level=high</code> every Monday (and on manual dispatch), with two documented ignores for dev-only advisories.</p><h2 id="release-process" tabindex="-1">Release process <a class="header-anchor" href="#release-process" aria-label="Permalink to &quot;Release process&quot;">​</a></h2><p><code>.github/workflows/release.yml</code> runs on every push to <code>main</code>:</p><ol><li>Checks out the full history, sets up Node 24 with the npm registry and the pinned Bun.</li><li><code>bun install --frozen-lockfile</code>, then <code>lint</code>, <code>type-check</code>, <code>build</code>, <code>test</code> and <code>check:package</code>.</li><li>Runs <code>changesets/action</code>: <ul><li>while changesets are pending, it opens or updates a pull request titled <code>chore(release): version packages</code>;</li><li>when that pull request is merged, it runs <code>bun run release</code> (<code>changeset publish</code>) and creates GitHub releases.</li></ul></li></ol><p>Publishing uses npm provenance (<code>NPM_CONFIG_PROVENANCE=true</code> with <code>id-token: write</code>), so provenance is only produced by CI. Authentication currently uses the <code>NPM_CONFIG_TOKEN</code> repository secret; the plan is to move every package to npm trusted publishing and remove the token. Do not run <code>npm publish</code> by hand.</p><p>After a release, verify from outside the repository (inside it, <code>npx</code> resolves the workspace):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mfe-forge@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mfe-forge@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>The site is built with VitePress from <code>docs/</code>. <code>deploy-docs.yml</code> builds <code>docs/.vitepress/dist</code> and deploys it with <code>actions/deploy-pages</code> when <code>docs/**</code>, a package README or the workflow changes on <code>main</code>, or on manual dispatch. The repository&#39;s Pages source must be set to <strong>GitHub Actions</strong> for the deployment to take effect.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # local preview with hot reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # what CI runs; fails on dead links</span></span></code></pre></div><p>Use relative links between pages.</p>`,36)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
